window.marked={parse:function(s){return String(s).replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/```([\s\S]*?)```/g,function(_,c){return '<pre><code>'+c.replace(/[&<>]/g,function(x){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[x]})+'</code></pre>'}).replace(/\n\n/g,'</p><p>').replace(/^/,'<p>').replace(/$/,'</p>')}};
